<div class="page-title">Fee Report</div><p class="page-subtitle">Understand how trading fees affect your net returns</p><div class="stats-grid"><div class="metric"><div class="label">Total Fees</div><div class="value negative"><?=number_format($a['summary']['fees'],2)?></div><div class="hint">All closed trades</div></div><div class="metric"><div class="label">Fee Impact</div><div class="value warning"><?=number_format($a['fee_impact']['fee_pct_of_gross_profit']??0,1)?>%</div><div class="hint">Fees as % of gross profit</div></div><div class="metric"><div class="label">Gross P&amp;L</div><div class="value positive"><?=number_format($a['fee_impact']['gross_pnl'],2)?></div><div class="hint">Before fees</div></div><div class="metric"><div class="label">Net P&amp;L</div><div class="value <?=($a['summary']['net_pnl']>=0?'positive':'negative')?>"><?=number_format($a['summary']['net_pnl'],2)?></div><div class="hint">After fees</div></div></div><?php if(($a['fee_impact']['fee_pct_of_gross_profit']??0)>10):?><div class="alert">⚠ High fee impact warning: fees are consuming a significant share of your gross profit. Consider optimizing trading frequency and position sizing.</div><?php endif;?><div class="report-grid"><div class="card"><h2>Fee Breakdown by Asset</h2><div class="sub">Which assets cost you the most in fees</div><?php foreach($assets as $x):$pct=$a['summary']['fees']>0?100*(float)$x['fees']/$a['summary']['fees']:0;?><div class="bar-row"><span><?=e($x['symbol'])?></span><div class="bar-track"><div class="bar-fill" style="width:<?=min(100,$pct)?>%"></div></div><strong><?=number_format((float)$x['fees'],2)?></strong></div><?php endforeach;if(!$assets):?><p class="muted">No fee data yet.</p><?php endif;?></div><div class="card"><h2>System Fee Impact</h2><div class="sub">How fees affect each trading system</div><?php foreach($systems as $x):?><div class="bar-row"><span><?=e($x['name']??'Unassigned')?></span><div class="bar-track"><div class="bar-fill" style="width:<?=min(100,(float)$x['fees'])?>%"></div></div><strong><?=number_format((float)$x['fees'],2)?></strong></div><?php endforeach;if(!$systems):?><p class="muted">No system fee data yet.</p><?php endif;?></div><div class="card full"><h2>Monthly Fee Trends</h2><div class="sub">Track your fee burden over time</div><canvas id="feeChart" height="90"></canvas></div></div><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script nonce="<?=e(csp_nonce())?>">const months={};<?php foreach($a['trades'] as $t):$m=date('Y-m',strtotime((string)$t['closed_at']));?>months['<?=e($m)?>']=(months['<?=e($m)?>']||0)+<?=json_encode((float)$t['fees'])?>;<?php endforeach;?>new Chart(document.getElementById('feeChart'),{type:'line',data:{labels:Object.keys(months),datasets:[{data:Object.values(months),borderColor:'#ec6a4f',borderWidth:1.5,pointRadius:2,tension:.25}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{x:{ticks:{font:{size:8}}},y:{ticks:{font:{size:8}}}}}});</script>
